package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMlDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("സുബ്ബഹുൻ കുദ്ദുസ് (റുകു & സുജൂദ്)", "(അല്ലാഹു) ഏറ്റവും മഹത്വമുള്ളവനും പരമപവിത്രനും മലക്കുകൾക്കും ആത്മാവിനും (ജിബ്രിൽ) നാഥനുമാണ്.", "റുക്കുവിലും സുജൂദിലും.", "നബി (സ) ഇത് റുക്കുവിലും സുജൂദിലും പാരായണം ചെയ്തു."),
        "dua_sujood_dhanbi_kullah" to DuaText("സുജൂദിൽഃ എൻ്റെ എല്ലാ പാപങ്ങളും ക്ഷമിക്കുക.", "അല്ലാഹുവേ, ചെറുതും വലുതും ആദ്യത്തേതും അവസാനത്തേതും തുറന്നതും മറഞ്ഞിരിക്കുന്നതുമായ എന്റെ പാപങ്ങളെല്ലാം എന്നോട് ക്ഷമിക്കണമേ.", "സുജൂദിൽ.", "ദുആകൾക്ക് ഉത്തരം നൽകുന്ന സ്ഥലമാണ് പ്രോസ്റ്റ്രേഷൻ."),
        "dua_sujood_ridaka" to DuaText("നിങ്ങളുടെ സന്തോഷത്തിൽ അഭയം തേടുക", "അല്ലാഹുവേ, നിൻറെ കോപത്തിൽ നിന്ന് നിൻറെ ഇഷ്ടത്തിൽ ഞാൻ അഭയം തേടുന്നു. നിൻറെ ശിക്ഷയിൽ നിന്ന് നിൻറെ മാപ്പിലും. നിന്നിൽ നിന്ന് ഞാൻ അഭയം തേടുന്നു. എനിക്ക് നിന്നെ പൂർണ്ണമായും സ്തുതിക്കാൻ കഴിയില്ല. നീ നിന്നെത്തന്നെ സ്തുതിച്ചതുപോലെ തന്നെയാണ്.", "സുജൂദിൽ-ആയിഷ (റ) പ്രവാചകൻ (സ) ഇത് പറയുന്നത് കേട്ടു.", "നബി (സ) യുടെ ഒരു സുജൂദ് ദുആ."),
        "dua_tashahhud" to DuaText("താഷാഹുദ് (അറ്റ്-തഹിയാത്ത്)", "വാക്കാലുള്ളതും ശാരീരികവും സാമ്പത്തികവുമായ ആരാധനകൾ എല്ലാം അല്ലാഹുവിനാണ്. നബിയേ, നിങ്ങൾക്ക് സമാധാനവും അല്ലാഹുവിൻറെ കാരുണ്യവും അവൻറെ അനുഗ്രഹങ്ങളും ഉണ്ടാകട്ടെ. ഞങ്ങൾക്കും അല്ലാഹുവിൻറെ സൽക്കർമ്മികളായ ദാസന്മാർക്കും സമാധാനം ഉണ്ടാകട്ടെ. അല്ലാഹുവല്ലാതെ ആരാധിക്കപ്പെടാൻ ആർക്കും അവകാശമില്ലെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. മുഹമ്മദ് സൽഹർ അല്ലാഹുവാണ് അവൻറെ ദാസനും ദൂതനും എന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു.", "ഓരോ യോഗത്തിലും-അബ്ദുല്ല ഇബ്നു മസൂദ് (റ) (ഹനാഫി സമ്പ്രദായം) വിവരിക്കുന്നു.", "ഖുർആനിലെ ഒരു സൂറത്ത് പോലെ പ്രവാചകൻ അത് പഠിപ്പിച്ചു."),
        "dua_sajdah_tilawah" to DuaText("പാരായണത്തിൻ്റെ സജ്ജ്ദാഹ്", "അതിനെ സൃഷ്ടിച്ചവനും തൻ്റെ ശക്തിയാലും ശക്തിയാലും അതിൻ്റെ കേൾവിയും കാഴ്ചയും പുറപ്പെടുവിച്ചവനും എൻ്റെ മുഖം സാഷ്ടാംഗം നമസ്കരിക്കപ്പെട്ടിരിക്കുന്നു.", "പാരായണത്തിൻ്റെ സാഷ്ടാംഗ നമസ്കാരത്തിൽ.", "നബി (സ) നബി (സ) രാത്രിയിൽ സാഷ്ടാംഗ നമസ്കാരത്തിൽ ഇത് പറഞ്ഞു."),
        "dua_after_witr" to DuaText("വിട്രിനുശേഷം", "പരമപവിത്രനായ രാജാവിന് മഹത്വം ഉണ്ടാകട്ടെ.", "മൂന്ന് തവണ വിർ സലാം കഴിഞ്ഞ്, മൂന്നാം തവണ ശബ്ദം ഉയർത്തി.", "നബി (സ) വിർഹത്തിനുശേഷം ഇത് പറഞ്ഞു."),
        "dua_tahajjud_nur" to DuaText("തഹജ്ജൂദ് ഉദ്ഘാടന പ്രാർത്ഥന", "അല്ലാഹുവേ, നീയാണ് സ്തുതി; നീ ആകാശങ്ങളുടെയും ഭൂമിയുടെയും അവയ്ക്കുള്ളിലെല്ലാം പരിപാലകൻ. നീയാണ് സ്തുതി. നീയാണ് ആകാശങ്ങളുടെയും ഭൂമിയുടെയും അവയ്ക്കുള്ളിലെ എല്ലാറ്റിന്റെയും പ്രകാശം. നീയാണ് സ്തുതി. നീയാണ് സത്യം, നിൻറെ വാഗ്ദാനം സത്യമാണ്, നിന്നുമായുള്ള കൂടിക്കാഴ്ച സത്യമാണ്, നിൻറെ വചനം സത്യമാണ്, പറുദീസ സത്യമാണ്, നരകം സത്യമാണ്, പ്രവാചകന്മാർ സത്യമാണ്, മുഹമ്മദ് സൽഹർ അല്ലാഹുവാണ് സത്യം, മണിക്കൂർ സത്യമാണ്.", "രാത്രി പ്രാർത്ഥന (തഹജ്ജുദ) (ദുആയുടെ പ്രാരംഭ ഭാഗം) ആരംഭിക്കുമ്പോൾ.", "നബി (സ) അത് പഠിച്ചത് തഹജ്ജുദിലേക്ക് (മുഴുവൻ ദുആ അൽ-ബുഖാരി) എഴുന്നേറ്റപ്പോഴാണ്."),
        "dua_rabba_jibrail" to DuaText("തർക്കവിഷയങ്ങളിൽ എന്നെ നയിക്കുക", "ആകാശങ്ങളുടെയും ഭൂമിയുടെയും സ്രഷ്ടാവായ ജിബ്രിലിന്റെയും മീഖായിൽ, ഇസ്റഫീലിന്റെയും രക്ഷിതാവായ അല്ലാഹുവേ, അദൃശ്യവും ദൃശ്യവും അറിയുന്നവനും ആകുന്നു. നിൻറെ ദാസന്മാർ തമ്മിൽ അവർ ഭിന്നിച്ചിരുന്ന കാര്യങ്ങളിൽ നീ വിധി പറയും. നിൻറെ അനുമതിയോടെ എന്നെ സത്യത്തിലേക്ക് നയിക്കുക. ഭിന്നതയുണ്ടായിരുന്ന കാര്യങ്ങളിൽ. തീർച്ചയായും നീ ഉദ്ദേശിക്കുന്നവരെ നീ നേർവഴിയിലാക്കുന്നു.", "തഹജ്ജൂദിൻറെ തുടക്കത്തിൽ-വിയോജിപ്പുകൾക്കിടയിൽ സത്യത്തിലേക്കുള്ള മാർഗനിർദേശത്തിനായി.", "നബി (സ) ഈ ദുആയോടെയാണ് രാത്രി പ്രാർത്ഥന ആരംഭിച്ചത്."),
        "dua_going_to_mosque_nur" to DuaText("പള്ളിയിലേക്ക് (പ്രകാശത്തിൻ്റെ ദുആ) പോകുന്നു", "അല്ലാഹുവേ, എൻറെ ഹൃദയത്തിൽ പ്രകാശം, എൻറെ കണ്ണിൽ പ്രകാശം, എൻറെ ചെവിയിൽ പ്രകാശം, എൻറെ വലത് വശത്ത് പ്രകാശം, എൻറെ ഇടതുവശത്ത് പ്രകാശം, എൻറെ മുകളിൽ പ്രകാശം, എൻറെ താഴെ പ്രകാശം, എൻറെ മുന്നിൽ പ്രകാശം, എൻറെ പിന്നിൽ പ്രകാശം എന്നിവ സ്ഥാപിച്ച് എനിക്ക് പ്രകാശം നൽകുക.", "ഫജ്റിനായി പള്ളിയിൽ പോകുമ്പോൾ.", "പ്രവാചകൻ സൽഹുല്ലാഹ്ലാഹു അലൈഹി വസല്ലം പ്രാർത്ഥനയ്ക്ക് പോകുമ്പോൾ ഇത് പാരായണം ചെയ്തു."),
        "dua_waswasa_salah" to DuaText("സലാഹിൽ വാസവാസ (ഖിൻസാബ്)", "ശപിക്കപ്പെട്ട ഷൈത്താൻ എന്നവനിൽനിന്ന് ഞാൻ അല്ലാഹുവിൽ അഭയം തേടുന്നു.", "പ്രാർത്ഥനയ്ക്കിടെ പൈശാചികമായ മന്ത്രിപ്പുകൾ വരുമ്പോൾ, അഭയം തേടുകയും മൂന്ന് തവണ ഇടതുവശത്ത് ചെറുതായി തുപ്പുക.", "ഉസ്മാൻ ഇബ്നു അബിൽ-അസ് (റ) ഇത് ചെയ്യുകയും, ആ ശബ്ദങ്ങൾ ഇല്ലാതാവുകയും ചെയ്തു."),
        "dua_alimal_ghayb" to DuaText("അദൃശ്യതയെ അറിയുന്നയാൾ", "അദൃശ്യവും ദൃശ്യവും അറിയുന്നവനും ആകാശങ്ങളുടെയും ഭൂമിയുടെയും സ്രഷ്ടാവും എല്ലാറ്റിൻറെയും രക്ഷിതാവും പരമാധികാരിയുമായ അല്ലാഹുവേ, നിന്നല്ലാതെ ദൈവമില്ലെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. എൻറെ തിന്മയിൽ നിന്നും ഷൈത്താൻറെ തിന്മയിൽ നിന്നും അവൻറെ ശിർക്കിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "രാവിലെയും വൈകുന്നേരവും ഉറങ്ങുന്നതിനുമുമ്പും-നബി (സ) അത് അബൂബക്കറിനെ (റ) പഠിപ്പിച്ചു.", "സ്വയം, ഷൈതൻ എന്നിവയുടെ തിന്മകളിൽ നിന്നുള്ള സംരക്ഷണം."),
        "dua_fitratil_islam" to DuaText("ഇസ്ലാമിന്റെ ഫിത്രയിൽ", "ഇസ്ലാമിന്റെ ഫിത്രയിൽ, ആത്മാർത്ഥതയുടെ വചനത്തിൽ, നമ്മുടെ പ്രവാചകൻ മുഹമ്മദ് സല്ലല്ലാഹു അലൈഹി വസല്ലമിന്റെ മതത്തിലും, നീതിമാനും മുസ്ലിമുമായ, ബഹുദൈവവിശ്വാസികളിൽ പെട്ടവനല്ലാത്ത നമ്മുടെ പിതാവ് ഇബ്രാഹിമിന്റെ (അ. സ.) വഴിയിലും നാം പ്രഭാതത്തിൽ പ്രവേശിച്ചു.", "രാവിലെ.", "എല്ലാ ദിവസവും രാവിലെ ഒരാളുടെ വിശ്വാസം പുതുക്കുക."),
        "dua_amsayna_fitrah" to DuaText("ഇസ്ലാമിന്റെ ഫിത്രയിലെ സായാഹ്നം", "ഇസ്ലാമിന്റെ ഫിത്രയിൽ, ആത്മാർത്ഥതയുടെ വചനത്തിൽ, ഞങ്ങളുടെ പ്രവാചകൻ മുഹമ്മദ് സല്ലല്ലാഹു അലൈഹി വസല്ലമിന്റെ മതത്തിലും, നീതിമാനും മുസ്ലിമുമായ ഞങ്ങളുടെ പിതാവ് ഇബ്രാഹിമിന്റെ (എ. എസ്) വഴിയിലും, ബഹുദൈവവിശ്വാസികളിൽ പെട്ടവരല്ലാത്ത സായാഹ്നത്തിലാണ് ഞങ്ങൾ പ്രവേശിച്ചത്.", "വൈകുന്നേരങ്ങളിൽ.", "ഓരോ വൈകുന്നേരവും ഒരാളുടെ വിശ്വാസം പുതുക്കുക."),
        "dua_tahleel_10_fajr" to DuaText("ഫജ്റിനും മഗ്രിബിനും ശേഷം പത്ത് തഹ്ലീൽ", "അല്ലാഹുവല്ലാതെ ആരാധനയ്ക്ക് അർഹനായി മറ്റാരുമില്ല. അവൻ ഏകനാണ്, അവന് പങ്കാളികളില്ല. അവന്നാകുന്നു ആധിപത്യം. അവന്നാകുന്നു സ്തുതി. അവൻ ജീവൻ നൽകുകയും മരണമുണ്ടാക്കുകയും ചെയ്യുന്നു. അവൻ എല്ലാറ്റിനും കഴിവുള്ളവനാകുന്നു.", "ഫജ്റിനും (മഗ്രിബിനും) ശേഷം പത്ത് തവണ, നിങ്ങളുടെ ഇരിപ്പിടത്തിൽ നിന്നോ സംസാരത്തിൽ നിന്നോ മാറുന്നതിന് മുമ്പ്.", "പത്ത് സൽപ്രവൃത്തികൾ, പത്ത് പാപങ്ങൾ മായ്ച്ചുകളയപ്പെട്ടു, പത്ത് റാങ്കുകൾ ഉയർത്തപ്പെട്ടു, ദിവസം മുഴുവൻ ശൈതാനത്തിൽ നിന്ന് സംരക്ഷണം ലഭിച്ചു."),
        "dua_la_hawla_kanz" to DuaText("ജന്നയുടെ ഒരു നിധി", "അല്ലാഹുവല്ലാതെ മറ്റൊരു ശക്തിയും ശക്തിയുമില്ല.", "പലപ്പോഴും, എല്ലായ്പ്പോഴും.", "പറുദീസയുടെ നിധികളിൽ ഒന്നാണിത്."),
        "dua_four_beloved_words" to DuaText("ഏറ്റവും പ്രിയപ്പെട്ട നാല് വാക്കുകൾ", "അല്ലാഹുവിന് സ്തുതി, എല്ലാ സ്തുതിയും അല്ലാഹുവിനാണ്, അല്ലാഹുവല്ലാതെ ആരാധിക്കപ്പെടാൻ ആർക്കും അവകാശമില്ല, അല്ലാഹു ഏറ്റവും വലിയവനാണ്.", "അല്ലാഹുവിന് ഏറ്റവും പ്രിയപ്പെട്ട വാക്കുകൾ.", "സൂര്യൻ ഉദിക്കുന്ന എല്ലാറ്റിനെക്കാളും അവർ പ്രവാചകന് പ്രിയപ്പെട്ടവരാണ്."),
        "dua_two_light_words" to DuaText("നാവിൽ തിളങ്ങുന്ന രണ്ട് വാക്കുകൾ", "അല്ലാഹുവിന് സ്തുതി, എല്ലാ സ്തുതിയും അവനുതന്നെയാണ്; പ്രതാപിയായ അല്ലാഹുവിന് സ്തുതി.", "നാവിൽ വെളിച്ചം, സ്കെയിലിൽ ഭാരം.", "ഏറ്റവും കരുണാനിധിയോട് സ്നേഹമുള്ളവനും നാവിൽ പ്രകാശവും സ്കെയിലിൽ ഭാരവുമുള്ളവനും. (ബുഖാരി അവസാന ഹദീസ്)"),
        "dua_ya_dhal_jalal" to DuaText("യാ ധൽ-ജലാലി വാൾ-ഇക്രം", "ഓ, ബഹുമാനത്തിൻ്റെയും മഹത്വത്തിൻ്റെയും ഉടമയെ!", "നബി (സ) യുടെ സൽഹ-അലി-അൽ-സലീം നിർദ്ദേശത്തിൽ അത് മുറുകെപ്പിടിക്കുക.", "നബി (സ) പറഞ്ഞുഃ'യാ ധൽ-ജലാലി വാൾ-ഇക്രം'മുറുകെ പിടിക്കുക."),
        "dua_sleep_wadatu_janbi" to DuaText("നിൻറെ നാമത്തിൽ ഞാൻ കിടക്കുന്നു.", "എൻറെ രക്ഷിതാവേ, അങ്ങയുടെ നാമത്തിൽ ഞാൻ എൻറെ പക്ഷം വെക്കുന്നു. അങ്ങയുടെ നാമത്തിൽ ഞാൻ ഉയിർത്തെഴുന്നേൽക്കുന്നു. അങ്ങു എൻറെ ആത്മാവിനെ സ്വീകരിക്കുകയാണെങ്കിൽ, അങ്ങയോട് കരുണ കാണിക്കുകയും, അതിനെ വിട്ടയക്കുകയാണെങ്കിൽ അങ്ങയുടെ നീതിമാന്മാരായ ദാസന്മാരെ സംരക്ഷിക്കുന്നതുപോലെ അതിനെ സംരക്ഷിക്കുകയും ചെയ്യുക.", "കിടക്ക പൊരിച്ച ശേഷം കിടന്നുറങ്ങുക.", "ഉറങ്ങുന്നതിനുമുമ്പ് ഒരാളുടെ ആത്മാവിനെ അല്ലാഹുവിന് സമർപ്പിക്കുക."),
        "dua_sleep_khalaqta_nafsi" to DuaText("നീയാണ് എൻ്റെ ആത്മാവിനെ സൃഷ്ടിച്ചത്.", "അല്ലാഹുവേ, നീ എൻറെ ആത്മാവിനെ സൃഷ്ടിച്ചു. നീ അത് ഏറ്റെടുക്കും. അതിൻറെ മരണവും അതിൻറെ ജീവനും നിനക്കുള്ളതാണ്. നീ അതിനെ നിലനിർത്തുകയാണെങ്കിൽ അതിനെ സംരക്ഷിക്കുക. നീ അതിനെ മരിപ്പിക്കുകയാണെങ്കിൽ അതിന് മാപ്പ് നൽകുക. അല്ലാഹുവേ, ഞാൻ നിന്നോടുതന്നെ ക്ഷേമത്തിനായി യാചിക്കുന്നു.", "ഉറങ്ങുന്നതിനുമുമ്പ്-ഇബ്നു ഉമർ (റ) വിവരിച്ചിരിക്കുന്നു.", "ഉറക്കസമയത്ത് ഇത് പറയണമെന്ന് പ്രവാചകൻ സൽഹഅലിഹ് വസ്ൽമ നിർദ്ദേശിച്ചു."),
        "dua_sleep_atamana" to DuaText("ഉറങ്ങുന്നതിനുമുമ്പ് നന്ദി", "ഞങ്ങൾക്ക് ഭക്ഷണം നൽകുകയും, ഞങ്ങൾക്ക് പാനീയം നൽകുകയും, ഞങ്ങൾക്ക് മതിയായ അഭയം നൽകുകയും ചെയ്ത അല്ലാഹുവിന് സ്തുതി. അവർക്ക് മതിയായ ആശ്രയമോ ആശ്രയമോ നൽകാൻ ആരുമില്ലാത്ത എത്ര പേരുണ്ട്.", "ഉറങ്ങാൻ പോകുമ്പോൾ.", "ഉറങ്ങാൻ പോകുമ്പോഴാണ് നബി (സ) ഇത് പറഞ്ഞത്."),
        "dua_sleep_rabbas_samawat" to DuaText("സ്വർഗ്ഗത്തിൻറെ കർത്താവ്-നമ്മുടെ കടം അടയ്ക്കുക", "ആകാശങ്ങളുടെയും ഭൂമിയുടെയും പ്രതാപിയുടെയും സിംഹാസനത്തിന്റെയും രക്ഷിതാവായ അല്ലാഹുവേ, എല്ലാറ്റിൻറെയും രക്ഷിതാവും, വിത്തുകളുടെയും ഈന്തപ്പനയുടെയും സ്രഷ്ടാവുമായ ഞങ്ങളുടെ രക്ഷിതാവേ, തൌറാത്തിൻറെയും ഇൻജീലിൻറെയും ഫുർഖാനിൻറെയും വെളിപ്പെടുത്തുന്നവനും, നിങ്ങൾ മുൻവശത്ത് പിടിച്ചിരിക്കുന്ന എല്ലാറ്റിൻറെയും തിന്മയിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു. അല്ലാഹുവേ, നീ ആദ്യത്തെയാളാണ്, നിനക്ക് മുമ്പ് ഒന്നുമില്ല. നീ അവസാനത്തെയാളാണ്, നിനക്ക് ശേഷം ഒന്നുമില്ല. നീയാണ് ഏറ്റവും വ്യക്തമായവൻ, നിനക്ക് മുകളിലുള്ളതായി ഒന്നുമില്ല. നീയാണ് മറഞ്ഞിരിക്കുന്നവൻ. നിന്നിൽ നിന്ന് മറഞ്ഞിരിക്കുന്നതായി ഒന്നുമില്ല. ഞങ്ങൾക്കുവേണ്ടി ഞങ്ങളുടെ കടം തീർക്കുകയും ഞങ്ങളെ ദാരിദ്ര്യത്തിൽ നിന്ന് മോചിപ്പിക്കുകയും ചെയ്യുക.", "ഉറങ്ങുന്നതിനുമുമ്പ്, വലതുവശത്ത് കിടക്കുക-ഫാത്തിമയെ (റ) പഠിപ്പിക്കുക.", "കടത്തിൽ നിന്നും കഷ്ടപ്പാടുകളിൽ നിന്നും ആശ്വാസം ലഭിക്കുന്ന ഒരു ദുആ."),
        "dua_sleep_fear" to DuaText("ഉറക്കത്തിൽ ഭയമോ അസ്വസ്ഥതയോ", "അല്ലാഹുവിൻറെ കോപത്തിൽ നിന്നും ശിക്ഷയിൽ നിന്നും അവൻറെ ദാസന്മാരുടെ തിന്മകളിൽ നിന്നും പിശാചുക്കളുടെ കിംവദന്തികളിൽ നിന്നും അവർ എൻറെ അടുത്തേക്ക് വരുന്നതിൽ നിന്നും ഞാൻ അവൻറെ പൂർണ്ണമായ വചനങ്ങളിൽ അഭയം തേടുന്നു.", "ഉറക്കത്തിൽ ഭയമോ അസ്വസ്ഥതയോ അനുഭവപ്പെടുമ്പോൾ.", "അങ്ങനെ ചെയ്താൽ, ആ കാര്യം അവനെ ഉപദ്രവിക്കില്ല."),
        "dua_waking_afani" to DuaText("ഉണർന്നുകൊണ്ട്ഃ അവൻ എൻ്റെ ആത്മാവിനെ പുനഃസ്ഥാപിച്ചു.", "എന്റെ ശരീരത്തിന് ക്ഷേമം നൽകുകയും എന്റെ ആത്മാവ് എനിക്ക് തിരികെ നൽകുകയും അവനെ ഓർമ്മിക്കാൻ എന്നെ അനുവദിക്കുകയും ചെയ്ത അല്ലാഹുവിന് എല്ലാ സ്തുതികളും.", "ഉണർന്നപ്പോൾ.", "ഒരു പുതിയ പ്രഭാതത്തിന് നന്ദി."),
        "dua_allahu_rabbi" to DuaText("അല്ലാഹു, അല്ലാഹു എൻറെ രക്ഷിതാവാണ്.", "അല്ലാഹു, അല്ലാഹു എൻറെ രക്ഷിതാവാണ്; ഞാൻ അവനുമായി ഒരു പങ്കും പങ്കിടുന്നില്ല.", "ദുഃഖത്തിലോ സങ്കടത്തിലോ-പ്രവാചകൻ സൽഹഅല്ലാഹുൽ മുസ്ലിമിൻറെ (റ) ആസ്മ ബിൻത് ഉമൈസിനെ (റ) അത് പഠിപ്പിച്ചു.", "ദുരിതസമയങ്ങളിൽ തൌഹീദിനെ മുറുകെ പിടിക്കുക."),
        "dua_rahmataka_arju" to DuaText("നിൻറെ കാരുണ്യം ഞാൻ പ്രതീക്ഷിക്കുന്നു.", "അല്ലാഹുവേ, ഞാൻ പ്രതീക്ഷിക്കുന്നത് നിൻറെ കാരുണ്യമാണ്. അതിനാൽ എന്നെ ഒരു കണ്ണ് ചിമ്മുമ്പോൾ പോലും എനിക്ക് വിട്ടുകൊടുക്കരുത്. എൻറെ എല്ലാ കാര്യങ്ങളും നീ ശരിയാക്കുക. നിന്നല്ലാതെ ദൈവമില്ല.", "ദുരിതത്തിലായ ഒരാളുടെ ദുആ (ദാവത്ത് അൽ മക്രബ്).", "പ്രവാചകൻ സൽഹുല്ലാഹ്ലാഹു സൽമാൻ ഇതിനെ ദുരിതമനുഭവിക്കുന്നയാളുടെ ദുആ എന്ന് വിളിച്ചു."),
        "dua_against_enemy_ahzab" to DuaText("ശത്രുക്കളുടെ സൈന്യത്തിനെതിരെ", "വേദഗ്രന്ഥം വെളിപ്പെടുത്തുന്ന അല്ലാഹുവേ, വേഗത്തിൽ കണക്ക് കൂട്ടണികളെ പരാജയപ്പെടുത്തണമേ. അല്ലാഹുവേ, അവരെ പരാജയപ്പെടുത്തണമേ. അവരെ ഇളക്കുക.", "ശത്രുവിനെതിരെ-കോൺഫെഡറേറ്റുകളുടെ യുദ്ധത്തിന്റെ ദൌ.", "ശത്രുവിനെതിരെ പ്രവാചകൻറെ സലീം."),
        "dua_anta_adudi" to DuaText("നീയാണ് എൻ്റെ പിന്തുണ", "അല്ലാഹുവേ, നീ എന്റെ സഹായിയും സഹായിയുമാണ്. നിൻറെ പേരിൽ ഞാൻ ആസൂത്രണം ചെയ്യുന്നു. നിൻറെ പേരിൽ ഞാൻ മുന്നേറുന്നു. നിൻറെ പേരിൽ ഞാൻ പോരാടുന്നു.", "ഒരു മത്സരത്തിന് മുമ്പോ അല്ലെങ്കിൽ ഒരു വലിയ വെല്ലുവിളിയോ.", "പ്രവാചകൻ സൽഹുല്ലാഹ്ലാഹു സൽമാൻ യുദ്ധത്തിൽവെച്ചാണ് ഇത് പറഞ്ഞത്."),
        "dua_ikfinihim" to DuaText("അവർക്കെതിരെ എനിക്ക് മതി.", "അല്ലാഹുവേ, നീ ഉദ്ദേശിച്ചതുപോലെ എനിക്കവർക്കെതിരെ പോരാ.", "അടിച്ചമർത്തലുകളുടെ തിന്മയ്ക്കെതിരെ-പീപ്പിൾ ഓഫ് ദി ഡിച്ചിന്റെ കഥയിലെ ആൺകുട്ടിയുടെ ദുആ.", "അല്ലാഹു കുട്ടിയെ അടിച്ചമർത്തുന്നവരിൽ നിന്ന് രക്ഷിച്ചു."),
        "dua_qadarullah" to DuaText("എന്തെങ്കിലും മോശമായി സംഭവിക്കുമ്പോൾ", "അത് അല്ലാഹുവിൻറെ കൽപനയാണ്, അവൻ ഉദ്ദേശിച്ചത് അവൻ ചെയ്തു.", "അസുഖകരമായ എന്തെങ്കിലും സംഭവിക്കുമ്പോൾ,'ഇഫ് ഒൺലി'എന്ന് പറയുന്നതിനുപകരം.", "'ഇഫ് ഒൺലി'എന്നതുകൊണ്ട് ഷൈതാനിലേക്കുള്ള വാതിൽ തുറക്കുന്നു."),
        "dua_ala_kulli_hal" to DuaText("എല്ലാ സാഹചര്യങ്ങളിലും സ്തുതിക്കുക", "എല്ലാ സാഹചര്യങ്ങളിലും അല്ലാഹുവിനാണ് എല്ലാ സ്തുതിയും.", "ഇഷ്ടപ്പെടാത്ത എന്തെങ്കിലും സംഭവിക്കുമ്പോൾ.", "തനിക്ക് ഇഷ്ടപ്പെടാത്ത എന്തോ ഒന്ന് നേരിട്ടതിനെ തുടർന്നാണ് പ്രവാചകൻ ഇത് പറഞ്ഞത്."),
        "dua_dogs_barking" to DuaText("രാത്രിയിൽ നായ്ക്കളുടെ കുര കേൾക്കുന്നു", "ശപിക്കപ്പെട്ട ഷൈത്താൻ എന്നവനിൽനിന്ന് ഞാൻ അല്ലാഹുവിൽ അഭയം തേടുന്നു.", "രാത്രിയിൽ നായ്ക്കൾ കുരയ്ക്കുന്നതോ കഴുതയുടെ കുരയ്ക്കുന്നതോ കേൾക്കുമ്പോൾ.", "നിങ്ങൾ കാണാത്തതെന്താണെന്ന് അവർ കാണുന്നു."),
        "dua_leaving_home_adilla" to DuaText("വഴിതെറ്റിക്കപ്പെടുന്നതിൽ നിന്നുള്ള അഭയം", "അല്ലാഹുവേ, ഞാൻ വഴിതെറ്റിക്കപ്പെടാതിരിക്കുകയോ വഴിതെറ്റിക്കപ്പെടുകയോ ചെയ്യാതിരിക്കാനും, ഞാൻ തെറ്റ് ചെയ്യപ്പെടാതിരിക്കുകയോ തെറ്റ് ചെയ്യപ്പെടുകയോ ചെയ്യപ്പെടാതിരിക്കാനോ, ഞാൻ വിഡ്ഢിയായി പെരുമാറുകയോ വിഡ്ഢിയായി പെരുമാറപ്പെടുകയോ ചെയ്യപ്പെടാതിരിക്കാനോ, ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "വീട്ടിൽ നിന്ന് പുറത്തുപോകുമ്പോൾ-ഉം സലമ (റ) വിവരിക്കുന്നു.", "നബി (സ) വീട്ടിൽ നിന്ന് പോകുമ്പോഴെല്ലാം ഇത് പാരായണം ചെയ്തിരുന്നു."),
        "dua_ascending_descending" to DuaText("മുകളിലേക്കും താഴേക്കും", "(കയറുമ്പോൾ) അല്ലാഹു ഏറ്റവും വലിയവനാണ്.-അല്ലാഹുവിന് (താഴേക്ക് വരുമ്പോൾ) മഹത്വമുണ്ട്.", "ഒരു യാത്രയിൽ, മുകളിലേക്ക് പോകുമ്പോൾ'അല്ലാഹു അക്ബർ'എന്നും താഴേക്ക് വരുമ്പോൾ'സുഭാനല്ലാഹ്'എന്നും പറയുക.", "യാത്ര ചെയ്യുമ്പോൾ കമ്പാനിയൻസ് (ആർ. എ.) പരിശീലനം."),
        "dua_traveller_sahar" to DuaText("പുലർച്ചെക്ക് മുമ്പ് സഞ്ചാരികളുടെ ദുആ", "ഒരു ശ്രോതാവ് അല്ലാഹുവിൻറെ സ്തുതിയും അവൻറെ അനുഗ്രഹങ്ങളും കേട്ടിട്ടുണ്ട്. ഞങ്ങളുടെ രക്ഷിതാവേ, നീ ഞങ്ങളെ അനുഗമിക്കുകയും, നരകാഗ്നിയിൽ നിന്ന് അല്ലാഹുവിങ്കൽ അഭയം തേടുകയും ചെയ്യുക.", "ഒരു യാത്രയിൽ, പുലർച്ചെക്ക് മുമ്പ്.", "യാത്ര ചെയ്യുമ്പോൾ പ്രവാചകൻ സൽഹുല്ലാഹ്ലാഹു സൽമാൻ പുലർച്ചെ ഇത് പറഞ്ഞു."),
        "dua_zawwadakallah" to DuaText("യാത്രക്കാരനോട്ഃ അല്ലാഹു തഖ് വാ നൽകട്ടെ.", "നിങ്ങളുടെ യാത്രയ്ക്ക് അല്ലാഹു നിങ്ങൾക്ക് തക്വ നൽകുകയും നിങ്ങളുടെ പാപങ്ങൾ ക്ഷമിക്കുകയും നിങ്ങൾ എവിടെയായിരുന്നാലും നിങ്ങൾക്ക് നന്മ എളുപ്പമാക്കുകയും ചെയ്യട്ടെ.", "ഒരു സഞ്ചാരിയോട് വിടപറയുമ്പോൾ.", "യാത്ര പുറപ്പെടുന്ന ഒരാൾക്ക് പ്രവാചകൻ സൽഹഅലിഹ് വസ്ലം ഈ ദുആ നൽകി."),
        "dua_traveller_to_resident" to DuaText("പിന്നിൽ നിൽക്കുന്നവർക്കുള്ള യാത്രക്കാരൻ", "ഒരിക്കലും നഷ്ടപ്പെടാത്ത അല്ലാഹുവിനാണ് ഞാൻ നിങ്ങളെ സമർപ്പിക്കുന്നത്.", "കുടുംബത്തോട് വിടപറയുമ്പോൾ യാത്രക്കാരൻ പറഞ്ഞു.", "കുടുംബത്തിൻ്റെ സുരക്ഷ അല്ലാഹുവിന് സമർപ്പിക്കുക."),
        "dua_entering_village" to DuaText("ഒരു പട്ടണത്തിലോ ഗ്രാമത്തിലോ പ്രവേശിക്കുക", "ഏഴ് ആകാശങ്ങളുടെയും അവയുടെ നിഴലുകളുടെയും രക്ഷിതാവായ അല്ലാഹുവേ, ഏഴ് ഭൂമികളുടെയും അവ വഹിക്കുന്നവയുടെയും രക്ഷിതാവായ, പിശാചുക്കളുടെയും അവർ വഴിതെറ്റിക്കുന്നവയുടെയും രക്ഷിതാവായ, കാറ്റുകളുടെയും അവ ചിതറിച്ചുകളയുന്നവയുടെയും രക്ഷിതാവായ, ഈ പട്ടണത്തിൻറെയും അതിൻറെ ജനവിഭാഗത്തിൻറെയും നന്മ ഞങ്ങൾ നിന്നോടു യാചിക്കുന്നു. അതിൻറെ തിന്മയിൽ നിന്നും അതിൻറെ ജനവിഭാഗത്തിൻറെ തിന്മയിൽ നിന്നും അതിൻറെ തിന്മയിൽ നിന്നും ഞങ്ങൾ നിന്നോട് അഭയം തേടുന്നു.", "ഒരു പട്ടണത്തിലോ നഗരത്തിലോ പ്രവേശിക്കുന്നതിന് മുമ്പ്.", "നബി (സ) ഒരു പട്ടണത്തിൽ പ്രവേശിക്കാൻ ആഗ്രഹിക്കുമ്പോഴെല്ലാം ഇത് പാരായണം ചെയ്തിരുന്നു."),
        "dua_vehicle_stumbles" to DuaText("വാഹനം ഇടിച്ചിറങ്ങുമ്പോൾ", "അല്ലാഹുവിൻറെ നാമത്തിൽ.", "'ഷൈതൻ നശിക്കട്ടെ'എന്ന് പറയുന്നതിനുപകരം, പർവ്വതമോ വാഹനമോ തെന്നി വീഴുകയോ ഇടറി വീഴുകയോ ചെയ്യുമ്പോൾ.", "ബിസ്മില്ല എന്ന് പറയുന്നത് ശായ്താനെ ഈച്ചയുടെ വലിപ്പത്തിലേക്ക് ചുരുക്കുന്നു."),
        "dua_ajz_kasal_haram" to DuaText("ദുർബലതയിൽ നിന്നും വാർദ്ധക്യത്തിൽ നിന്നുമുള്ള അഭയം", "അല്ലാഹുവേ, നിസ്സഹായതയിൽ നിന്നും അലസതയിൽ നിന്നും ഭീരുത്വത്തിൽ നിന്നും വാർദ്ധക്യത്തിൽ നിന്നും ജീവിതത്തിന്റെയും മരണത്തിന്റെയും പരീക്ഷണങ്ങളിൽ നിന്നും ശവകുടീരത്തിന്റെ ശിക്ഷയിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "ഒരു സമഗ്രമായ ദൈനംദിന അഭയം.", "നബി (സ) പലപ്പോഴും ഒരു ദുആ ചെയ്യുമായിരുന്നു."),
    )
}
